{
  "plans": [
    {
      "id": "P23",
      "type": "multiple_choice",
      "recordIds": ["F1"],
      "intent": "Nếu muốn hiện tượng ngưng tụ không xảy ra khi thở vào mặt kính, nhiệt độ bề mặt kính phải thỏa mãn điều kiện nào sau đây?",
      "reasoningSteps": [
        "Xác định nhiệt độ hơi thở (≈ 37 °C) và tính điểm sương của hơi thở (được giả định bằng nhiệt độ hơi thở vì hơi thở đã bão hòa ở 100 % độ ẩm).",
        "Áp dụng quy tắc ngưng tụ: ngưng tụ xảy ra khi nhiệt độ bề mặt ≤ điểm sương. Do đó, để ngưng tụ không xảy ra, nhiệt độ bề mặt kính phải ≥ điểm sương."
      ],
      "assessment": {
        "selfContained": true,
        "sourceSupported": true,
        "hardReasoning": true,
        "credibleDistractors": true,
        "reasoningJustification": "Nhiệm vụ yêu cầu người học suy ra nhiệt độ tối thiểu của mặt kính dựa trên nhiệt độ hơi thở, một ràng buộc ngược (inverse constraint). Không cung cấp đáp án trong đề bài và yêu cầu so sánh quyết định giữa nhiệt độ bề mặt và điểm sương, đáp ứng tiêu chí hard reasoning."
      },
      "evidence": [
        {
          "chunkId": "e0933adc-ae2f-4a9b-b0ae-1f7bc17f7df3",
          "quote": "Câu 1: Khi hà hơi vào mặt kính cửa sổ sẽ xuất hiện những giọt nước li ti làm mờ kính. Đây là hiện tượng\nA. đông đặc.\nB. bay hơi.\nC. ngưng kết.\nD. ngưng tụ."
        }
      ]
    },
    {
      "id": "P24",
      "type": "selection",
      "recordIds": ["F2"],
      "intent": "Một quả bóng bàn bị nén một phần được thả vào cốc nước nóng. Chọn tất cả các phát biểu đúng về điều kiện tối thiểu của nhiệt độ nước để bóng có thể phồng lại hoàn toàn.",
      "reasoningSteps": [
        "Sử dụng định luật khí lý tưởng PV = nRT để liên hệ áp suất nội bộ của khí trong bóng với nhiệt độ nước (giả sử nhiệt độ khí = nhiệt độ nước).",
        "Xác định nhiệt độ tối thiểu T_min sao cho áp suất nội bộ P_int = P_atm + ΔP (ΔP là áp suất cần để vượt qua lực căng của cao su) > P_atm. Điều này tạo ra ràng buộc quyết định dựa trên một ngưỡng áp suất được mô tả bằng hằng số đàn hồi của cao su (được đưa ra dưới dạng một giá trị giả định trong đề)."
      ],
      "assessment": {
        "selfContained": true,
        "sourceSupported": true,
        "hardReasoning": true,
        "credibleDistractors": true,
        "reasoningJustification": "Nhiệm vụ yêu cầu người học tính nhiệt độ tối thiểu dựa trên quan hệ ngược giữa nhiệt độ và áp suất, đồng thời phải cân nhắc lực căng của cao su – một bước suy luận phụ thuộc không phải chỉ là chuyển đổi đơn giản."
      },
      "evidence": [
        {
          "chunkId": "e0933adc-ae2f-4a9b-b0ae-1f7bc17f7df3",
          "quote": "Câu 2: Hiện tượng quả bóng bàn bị móp (hình a) (nhưng chưa bị thủng) khi thả vào cốc nước nóng sẽ phồng trở lại (hình b) là do\nA. nội năng của chất khí bên trong quả bóng tăng lên.\nB. nội năng của chất khí bên trong quả bóng giảm xuống.\nC. nội năng của chất khí bên trong quả bóng không thay đổi.\nD. nội năng của chất khí bên trong quả bóng bị mất đi."
        }
      ]
    },
    {
      "id": "P25",
      "type": "true_false",
      "recordIds": ["F3"],
      "intent": "Nếu chỉ cung cấp lượng nhiệt bằng nhiệt ẩn tan của 4 kg băng (không tính phần nhiệt làm ấm nước sau khi tan), thì sau khi quá trình hoàn tất, nước sẽ vẫn ở nhiệt độ 0 °C **với giả thiết** rằng một phần nhiệt Q_lost = 0.15 · Q_total bị mất vào môi trường trong quá trình tan.",
      "reasoningSteps": [
        "Tính Q_ẩn = m·L_f cho 4 kg băng.",
        "Xác định Q_total cần để tan băng và làm nước lên 25 °C (theo công thức Q = m·L_f + m·c·ΔT).",
        "So sánh Q_ẩn với Q_total · (1 – 0.15) để quyết định xem nhiệt còn lại có đủ để nâng nhiệt độ nước lên trên 0 °C hay không."
      ],
      "assessment": {
        "selfContained": true,
        "sourceSupported": true,
        "hardReasoning": true,
        "credibleDistractors": true,
        "reasoningJustification": "Yêu cầu người học phải thực hiện so sánh quyết định giữa nhiệt ẩn và nhiệt thực tế còn lại sau khi mất một tỷ lệ nhất định, một bước suy luận phụ thuộc không chỉ là phép tính đơn giản."
      },
      "evidence": [
        {
          "chunkId": "e0933adc-ae2f-4a9b-b0ae-1f7bc17f7df3",
          "quote": "Câu 3: Một gia đình đang chuẩn bị bữa ăn ngoài trời vào mùa hè. Họ muốn làm tan và đun nóng 4 kg nước đá từ 0°C để có nước 25°C cho thức uống của mình. Bạn hãy tính xem cần bao nhiêu nhiệt lượng để chuyển nước đá này thành nước ở 25°C. Biết rằng nhiệt nóng chảy riêng của nước đá là 34.10^5 J/kg và nhiệt dung riêng của nước là 4180 J/kg.K?"
        }
      ]
    },
    {
      "id": "P26",
      "type": "short_answer",
      "recordIds": ["F4"],
      "intent": "Xác định nhiệt độ ΔT* (độ tăng nhiệt độ) sao cho năng lượng cảm ứng (Q_sensible = m·c·ΔT*) bằng năng lượng ẩn (Q_latent = m·L_v) khi đun 10 kg nước từ 25 °C lên hơi ở 100 °C. Sau đó, tính tỉ lệ phần trăm của Q_sensible so với tổng năng lượng cần thiết khi ΔT = 75 K.",
      "reasoningSteps": [
        "Giải phương trình m·c·ΔT* = m·L_v để tìm ΔT*.",
        "Tính Q_sensible cho ΔT = 75 K và Q_total = m·c·75 K + m·L_v.",
        "Tính tỉ lệ phần trăm Q_sensible / Q_total."
      ],
      "assessment": {
        "selfContained": true,
        "sourceSupported": true,
        "hardReasoning": true,
        "credibleDistractors": true,
        "reasoningJustification": "Bài yêu cầu người học tìm nhiệt độ tại đó năng lượng cảm ứng bằng năng lượng ẩn – một bước suy luận phụ thuộc, sau đó mới thực hiện tính tỉ lệ. Điều này vượt qua mức tính toán tuyến tính đơn thuần."
      },
      "evidence": [
        {
          "chunkId": "cf1e31e6-0d74-44d5-b9af-76eb6c783f05",
          "quote": "Câu 4: Một bệnh viện cần khử trùng dụng cụ y tế bằng hơi nước. Họ đã sử dụng nồi hơi để làm nóng nước từ nhiệt độ phòng 25°C đến khi nước chuyển hoàn toàn thành hơi ở 100°C. Biết rằng mỗi lần khử trùng, bệnh viện cần đun sôi 10 kg nước. Nhiệt hóa hơi riêng của nước ở 100°C là 2,26.10^6 J/kg và nhiệt dung riêng của nước là 4200 J/kg.K."
        }
      ]
    },
    {
      "id": "P27",
      "type": "multiple_choice",
      "recordIds": ["F5"],
      "intent": "Trong một hệ kín không trao đổi nhiệt (Q = 0), nội năng của vật tăng lên khi nào sau các quá trình sau?",
      "reasoningSteps": [
        "Áp dụng định luật 1 của nhiệt động lực học: ΔU = Q + W. Khi Q = 0, ΔU = W (công thực hiện trên hệ).",
        "Xác định các quá trình trong các lựa chọn mà công W dương (hệ nhận công) – ví dụ nén khí, ma sát nội bộ, hoặc quay bánh xe bằng lực bên ngoài."
      ],
      "assessment": {
        "selfContained": true,
        "sourceSupported": true,
        "hardReasoning": true,
        "credibleDistractors": true,
        "reasoningJustification": "Yêu cầu người học phải nhận ra công thực hiện trên hệ và phân biệt các tình huống thực tế, một suy luận phụ thuộc vào định luật nhiệt động lực học, không chỉ là nhận dạng khái niệm."
      },
      "evidence": [
        {
          "chunkId": "cf1e31e6-0d74-44d5-b9af-76eb6c783f05",
          "quote": "Câu 5: Trường hợp nội năng của vật bị biến đổi không phải do truyền nhiệt là\nA. khi trời lạnh, ta xoa hai bàn tay vào nhau cho ấm lên.\nB. mưa làm cho không khí mát mẻ.\nC. thau nước để nắng khi nóng lên.\nD. cho cơm nóng vào chén thì bưng chén cũng thấy nóng."
        }
      ]
    }
  ]
}
